'use strict';
// Local design simulation only. No fetch, router endpoints, credentials, or service worker.
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 home:'<path d="m3 10 9-7 9 7v10H14v-6h-4v6H3Z"/>', devices:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>', usage:'<path d="M4 20V10m8 10V4m8 16v-7"/>', automations:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>', activity:'<path d="M4 5h2m4 0h10M4 12h2m4 0h10M4 19h2m4 0h10"/>', settings:'<path d="m9 3-1 3-3 1 1 4-2 2 2 3 3-1 2 3h3l1-3 3-1 1-3-2-2 1-3-3-1-1-3Z"/><circle cx="12" cy="11" r="3"/>', search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>', moon:'<path d="M20 15A9 9 0 0 1 9 3 9 9 0 1 0 20 15Z"/>', shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>', router:'<rect x="3" y="12" width="18" height="8" rx="2"/><path d="M6 12V4m12 8V4M7 16h1m4 0h1m4 0h1"/>', wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r="1"/>', arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', back:'<path d="M20 12H4m6-6-6 6 6 6"/>', tv:'<rect x="2" y="4" width="20" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>', laptop:'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="M2 20h20l-2-4H4Z"/>', server:'<rect x="4" y="3" width="16" height="7" rx="2"/><rect x="4" y="14" width="16" height="7" rx="2"/><path d="M8 6h.1M8 17h.1m5-11h4m-4 11h4"/>', game:'<path d="M7 7h10c3 0 5 11 3 12s-5-4-6-4h-4c-1 0-4 5-6 4S4 7 7 7Z"/><path d="M8 9v5m-2-2h4m6-2h.1m2 3h.1"/>', camera:'<path d="M3 7h12v11H3Zm12 4 6-3v10l-6-3M7 7l2-3h4"/>', pause:'<path d="M8 4v16m8-16v16"/>', add:'<path d="M12 4v16M4 12h16"/>', block:'<circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/>', bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5Zm5 3h4"/>', warning:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3h.1"/>', check:'<path d="m5 12 4 4L20 5"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>', help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2m-1 3h.1"/>', refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 14-1M5 18a8 8 0 0 0 14-1"/>', tune:'<path d="M3 6h18M3 12h18M3 18h18M7 3v6m10 0v6M9 15v6"/>', cloud:'<path d="M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5 5 0 0 1 1 11Z"/>', eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>', leaf:'<path d="M20 3C6 2 1 10 6 17s16 0 14-14ZM5 20 16 8"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.devices}</svg>`;
const tile = (name, large = false) => `<span class="symbol-tile${large ? ' large' : ''}">${icon(name)}</span>`;
const chip = (label, kind = '', name = '') => `<span class="chip ${kind}">${name ? icon(name) : ''}${label}</span>`;
const button = (text, action, variant = 'button', name = '') => `<button class="${variant}" data-action="${action}">${name ? icon(name) : ''}${text}</button>`;
const link = (text, href, variant = 'text-button', name = '') => `<a class="${variant}" href="#${href}">${name ? icon(name) : ''}${text}</a>`;
const head = (eyebrow, title, copy, actions = '') => `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div>${actions ? `<div class="actions">${actions}</div>` : ''}</div>`;
const section = (title, body, cls = '', extra = '') => `<section class="card ${cls}"><div class="section-head"><h2>${title}</h2>${extra}</div>${body}</section>`;
const ring = (percent, label = 'of daily budget') => `<div class="ring" style="--ring-fill:${percent}" role="img" aria-label="${percent}% ${esc(label)}"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="track" cx="60" cy="60" r="49" pathLength="100"/><circle class="value" cx="60" cy="60" r="49" pathLength="100"/></svg><div class="ring-label">${percent}%<small>${label}</small></div></div>`;
const devices = [
 {id:'01', name:'Pixel phone', cat:'Mobile', type:'devices', used:1.4, lan:.1, online:true, medium:'WiFi · 5 GHz', ip:'192.168.1.31', protected:true},
 {id:'02', name:'Samsung TV', cat:'Television', type:'tv', used:4.2, lan:12, online:true, medium:'WiFi · 5 GHz', ip:'192.168.1.50'},
 {id:'03', name:'Jellyfin server', cat:'Computer', type:'server', used:0, lan:11.8, online:true, medium:'Ethernet', ip:'192.168.1.20', protected:true, lanOnly:true},
 {id:'04', name:'PS5', cat:'Game console', type:'game', used:.6, lan:0, online:false, medium:'WiFi · 5 GHz', ip:'192.168.1.61'},
 {id:'05', name:'IP camera', cat:'IP camera', type:'camera', used:.1, lan:.1, online:true, medium:'WiFi · 2.4 GHz', ip:'192.168.1.71'},
 {id:'06', name:'Laptop', cat:'Laptop', type:'laptop', used:2.1, lan:0, online:true, medium:'WiFi · 5 GHz', ip:'192.168.1.41'}
];
const mac = d => `02-00-00-00-00-${d.id}`;
const state = {route:'/', scenario:'dry', selected:new Set(), deviceSearch:'', category:'all', online:'all', period:'week', group:'category', notifications:false, guest:true, quota:5, quotaAction:'Throttle', quotaDry:true, ruleSaved:false, ruleName:'Bedtime throttle', ruleTrigger:'Time window', ruleScope:'Samsung TV', ruleAction:'Throttle', ruleRate:256, ruleRevert:'When time window ends', ruleCooldown:60, ruleOnce:'Day', ruleStep:1, pending:[], applied:[], theme:'system', activity:'all', setupTested:false, protectedTV:false, dirty:false};
const isLive = () => state.scenario === 'enforcing';
const offline = () => state.scenario === 'offline';
const nextTick = 'Takes effect on the Agent’s next tick (about 3 min).';
let lastOpener = null;
let confirmCallback = null;
let undoCallback = null;
let toastTimer;
function initTheme(){
 try { state.theme = localStorage.getItem('netpilot-design-theme') || 'system'; } catch { state.theme = 'system'; }
 setTheme(state.theme);
}
function setTheme(theme){
 state.theme = theme;
 if(theme === 'system') document.documentElement.removeAttribute('data-theme'); else document.documentElement.dataset.theme = theme;
 $('#theme-select').value = theme;
 try {localStorage.setItem('netpilot-design-theme', theme);} catch { /* Optional local preference. */ }
}
function toast(message, undo){
 clearTimeout(toastTimer); undoCallback = undo || null;
 $('#snackbar').innerHTML = `<span>${esc(message)}</span><button data-action="${undo ? 'undo' : 'dismiss-toast'}">${undo ? 'Undo' : 'Dismiss'}</button>`;
 $('#snackbar').hidden = false;
 toastTimer = setTimeout(() => { if(!$('#snackbar').matches(':hover') && !$('#snackbar').contains(document.activeElement)) $('#snackbar').hidden = true; },10000);
}
function receipt(){
 if(state.pending.length) return `<div class="receipt" role="status"><div><strong>${state.pending.length} demo change${state.pending.length>1?'s':''} awaiting Agent</strong><p>${nextTick} Use “Simulate Agent tick” below to review confirmation.</p></div>${icon('clock')}</div>`;
 if(state.applied.length) return `<div class="receipt applied" role="status"><div><strong>Demo Agent confirmed</strong><p>${esc(state.applied[state.applied.length-1])} · simulated, no router command</p></div>${icon('check')}</div>`;
 return '';
}
function enqueue(description){ state.pending.push(description); state.applied=[]; render(false); toast(`Saved in demo. ${nextTick}`); }
function openSheet(title, body, footer){
 if(!$('#editor').open)lastOpener = document.activeElement; state.dirty=false;
 $('#editor-content').innerHTML = `<div class="sheet-head"><h2 id="editor-title">${title}</h2><button data-action="close-editor" class="icon-button" aria-label="Close editor">${icon('close')}</button></div><div class="sheet-body">${body}</div><div class="sheet-footer">${footer}</div>`;
 if(!$('#editor').open) $('#editor').showModal();
 const field = $('input,select,textarea', $('#editor-content')); if(field) field.focus();
}
function closeSheet(force=false){
 if(state.dirty&&!force){ confirmDialog('Discard changes?', 'Your unsaved demo changes will be lost.', 'Discard', () => closeSheet(true)); return; }
 $('#editor').close(); state.dirty=false; if(lastOpener && lastOpener.isConnected) lastOpener.focus();
}
function confirmDialog(title, text, label, callback){
 confirmCallback=callback;
 $('#confirm-content').innerHTML = `<h2 id="confirm-title">${esc(title)}</h2><p>${esc(text)}</p><div class="actions">${button('Cancel','cancel-confirm','outline')}${button(label,'accept-confirm','danger')}</div>`;
 $('#confirm').showModal(); $('[data-action="cancel-confirm"]', $('#confirm')).focus();
}
function chart(period = state.period, device = false){
 const labels = period === 'month' ? ['1–3','4–6','7–9','10–12','13–15','16'] : period === 'day' ? ['Today'] : ['Sat 10','Sun 11','Mon 12','Tue 13','Wed 14','Thu 15','Fri 16'];
 let vals = period === 'month' ? [35,44,39,41,46.6,8.4] : period === 'day' ? [8.4] : [13.2,16.5,18.4,15.8,17.1,22.2,8.4];
 let lans = period === 'month' ? [30,42,38,28,34,24] : period === 'day' ? [24] : [16,10,18,14,21,19,24];
 if(device && period === 'week'){ vals=[3.2,3.8,5.4,4.1,4.8,6.2,4.2]; lans=[8,7,9,10,8,10,12]; }
 const max = Math.max(...vals.map((v,i)=>v+lans[i]));
 return `<div class="usage-chart" role="img" aria-label="Internet and LAN usage, ${esc(period)}. Exact values in the data table below.">${vals.map((v,i)=>`<div class="chart-column"><div class="bar-pair"><div class="bar" style="--height:${v/max*140}px"></div><div class="bar lan" style="--height:${lans[i]/max*140}px"></div></div><small>${labels[i]}</small></div>`).join('')}</div><div class="legend"><span><i class="swatch"></i>Internet</span><span><i class="swatch lan"></i>LAN excluded · both endpoints</span></div><details><summary>View chart data</summary><table><caption>${esc(period)} usage · decimal GB · sample data</caption><thead><tr><th>Period</th><th>Internet GB</th><th>LAN GB</th></tr></thead><tbody>${vals.map((v,i)=>`<tr><td>${labels[i]}</td><td>${v}</td><td>${lans[i]}</td></tr>`).join('')}</tbody></table></details>`;
}
function consumers(){return [...devices].sort((a,b)=>b.used-a.used).slice(0,4).map(d=>`<div class="consumer">${tile(d.type)}<div><a href="#/devices/${mac(d)}"><strong>${esc(d.name)}</strong></a><div class="meter"><span style="--fill:${d.used/4.2*100}%"></span></div></div><div class="number">${d.used.toFixed(1)} <small>GB</small></div></div>`).join('');}
function home(){
 return head('Friday, 16 October','A little clarity for your network.','Your household at a glance. All times in Cairo.',button('Pause internet','pause','button','pause'))+
 `<div class="household"><div class="summary">${tile('router')}<div><h3>Archer AX53 ${chip(offline()?'Unavailable':'Last read 21:39',offline()?'warning':'ok')}</h3><p>${offline()?'Last successful read 20:51 · saved data below':'5 devices online · Agent completed a tick 3 min ago'}</p></div></div>${link('Network health','/settings/health','text-button','arrow')}</div>`+
 `<div class="grid"><section class="card hero span-8 tablet-full"><div class="section-head"><span class="eyebrow">Internet today</span>${chip('Sample household budget')}</div><div class="hero-body"><div><div class="big-number">8.4 <span>GB</span></div><p style="margin-block-start:12px">of a 15 GB daily budget</p><small>6.6 GB left to enjoy today</small></div>${ring(56)}</div><div class="meter"><span style="--fill:56%"></span></div><div class="row between" style="margin-block-start:16px"><small>Month · 214 of 300 GB</small>${link('Explore usage','/usage','text-button','arrow')}</div></section>
 ${section('Needs your attention',`<div class="notice">${icon('warning')}<div><h3>TV is at 84% of its daily quota</h3><p>${isLive()?'512 Kbps quota claim active in this example.':'Dry-run: it would slow down after 5 GB.'}</p><a href="#/devices/02-00-00-00-00-02">Review Samsung TV ${icon('arrow')}</a></div></div><div class="notice">${icon('devices')}<div><h3>New device: IP camera</h3><p>First seen in this sample household today. Review its category and protection.</p><a href="#/devices/02-00-00-00-00-05">Review device ${icon('arrow')}</a></div></div><div class="notice">${icon('leaf')}<div><h3>Verify your LAN traffic source</h3><p>A successful read doesn’t prove local streams are counted correctly.</p><a href="#/settings/traffic">Check usage confidence ${icon('arrow')}</a></div></div>${!state.notifications?`<div class="notice">${icon('bell')}<div><h3>Bring alerts to your phone</h3><p>No push subscription on this demo device.</p><a href="#/settings/notifications">Set up notifications ${icon('arrow')}</a></div></div>`:''}`,'span-4')}
 ${section('Top Internet consumers today',consumers(),'span-8',link('All devices','/devices'))}
 ${section('Restrictions & previews',`<div class="list-row"><div class="grow"><h3>Samsung TV</h3><p>${isLive()?'512 Kbps · two active claims':'512 Kbps · manual speed override'}</p>${chip(isLive()?'Quota + bedtime':'Manual limit','throttled')}</div>${button('Review','why','text-button')}</div><div class="list-row"><div class="grow"><h3>PS5</h3><p>Manual block · NetPilot record</p>${chip('Not router-verified','blocked')}</div>${button('Unblock','unblock','text-button')}</div><p class="hint">${isLive()?'Example enforcement only. Keep real quotas/rules in dry-run pending verification.':'Automatic quotas and rules are observing. Manual actions operate separately.'}</p>`,'span-4')}
 ${section('Make a quick adjustment',`<div class="quick-grid">${[['pause','Pause internet','For a little while','pause'],['add','Add bonus data','Choose device & period','bonus'],['block','Block a device','Direct router command','block'],['wifi',state.guest?'Guest WiFi · On':'Guest WiFi · Off','Review before changing','guest']].map(([i,t,s,a])=>`<button class="quick-action" data-action="${a}">${icon(i)}<strong>${t}</strong><small>${s}</small></button>`).join('')}</div><p class="hint">Pause and general bonus-data controls are proposed backend additions. All actions here are local simulations.</p>`,'span-12')}
 </div>`;
}
function restriction(d){return d.id==='02'?chip(isLive()?'512 Kbps · quota':'512 Kbps · manual','throttled'):d.id==='04'?chip('Blocked · recorded','blocked'):d.protected?chip('Protected','ok','shield'):chip('No restriction');}
function devicesPage(){
 return head('Your network','Devices','6 known devices · 5 online now',button('Refresh from router','refresh-router','outline','refresh'))+
 `<div class="toolbar"><label class="field search-field">Find a device<input id="device-search" type="search" value="${esc(state.deviceSearch)}" placeholder="Name, MAC or IP address"></label><label class="field">Category<select id="category-filter"><option value="all">All categories</option>${[...new Set(devices.map(d=>d.cat))].map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Connection<select id="online-filter"><option value="all">All devices</option><option value="online" ${state.online==='online'?'selected':''}>Online only</option><option value="offline" ${state.online==='offline'?'selected':''}>Offline only</option></select></label><label class="field">Group by<select id="group-filter"><option value="category" ${state.group==='category'?'selected':''}>Category</option><option value="none" ${state.group==='none'?'selected':''}>None</option><option disabled>Person · needs backend</option></select></label></div><div id="device-results"></div>`;
}
function renderDevices(){
 const q=state.deviceSearch.toLowerCase(); const filtered=devices.filter(d=>(state.category==='all'||d.cat===state.category)&&(state.online==='all'||d.online===(state.online==='online'))&&`${d.name} ${d.ip} ${mac(d)}`.toLowerCase().includes(q));
 const ordered=state.group==='category'?[...filtered].sort((a,b)=>a.cat.localeCompare(b.cat)):filtered;
 const select=d=>`<label class="select-box"><input type="checkbox" data-device="${d.id}" ${state.selected.has(d.id)?'checked':''} aria-label="Select ${esc(d.name)}"></label>`;
 const body=`${state.selected.size?`<div class="selection-bar"><strong>${state.selected.size} selected</strong><div class="actions">${button('Pause selected','pause','tonal','pause')}${button('Clear','clear-selection','text-button')}</div></div>`:''}`+
 (!ordered.length?`<div class="card empty-state">${tile('search')}<h2>No matching devices</h2><p>Try a name, MAC address or a different filter.</p>${button('Clear filters','clear-filters')}</div>`:
 `<div class="card table-scroll" style="padding:8px 16px"><table class="device-table"><caption class="screen-reader-only">Known devices, ${state.group==='category'?'grouped by category':'ungrouped'}</caption><thead><tr><th>Select</th><th>Device / category</th><th>Connection</th><th>Internet today</th><th>Restriction</th></tr></thead><tbody>${ordered.map(d=>`<tr><td>${select(d)}</td><td><div class="device-identity">${tile(d.type)}<div><a href="#/devices/${mac(d)}">${esc(d.name)}</a><small>${d.cat} · <bdi>${d.ip}</bdi></small></div></div></td><td>${chip(d.online?'Online':'Offline',d.online?'ok':'')}<small>${d.medium}</small></td><td><strong>${d.used.toFixed(1)} GB</strong><small>${d.lan?d.lan+' GB LAN excluded':'Internet only'}</small></td><td>${restriction(d)}</td></tr>`).join('')}</tbody></table></div><div class="device-cards">${ordered.map(d=>`<article class="card device-card"><div class="identity">${tile(d.type)}<div style="flex:1"><a href="#/devices/${mac(d)}">${esc(d.name)}</a><p class="hint" style="margin:4px 0 0">${d.cat} · ${d.online?'Online now':'Last seen 19:12'}</p></div>${select(d)}</div><div class="stats"><span><strong>${d.used.toFixed(1)} GB</strong><small> Internet today</small></span>${restriction(d)}</div><small><bdi>${d.ip}</bdi> · ${d.medium}</small></article>`).join('')}</div>`);
 $('#device-results').innerHTML=body;
}
function detail(){
 const id=state.route.split('/')[2];const d=devices.find(x=>mac(x)===id);if(!d)return empty('Device not found','This demo has six known devices.','Back to devices','/devices');
 const tv=d.id==='02';
 return `<div class="breadcrumbs">${link('Devices','/devices','text-button','back')}<span>/ ${esc(d.name)}</span></div><div class="identity-header">${tile(d.type,true)}<div><div class="eyebrow">${d.cat}</div><h1>${esc(d.name)}</h1><p class="muted"><bdi class="code">${mac(d)}</bdi> · ${d.ip}</p></div><div class="actions">${button('Pause','pause','button','pause')}${button('Edit identity','identity','outline','tune')}</div></div><div class="pills" style="margin-block-end:24px">${chip(offline()?'Observation stale':d.online?'Online · read 21:39':'Offline · seen 19:12',offline()?'warning':d.online?'ok':'')}${chip(d.medium)}${restriction(d)}</div><div class="grid">
 ${section('Internet usage',`<div class="stat-grid"><div><small>Today</small><div class="metric">${d.used.toFixed(1)} GB</div></div><div><small>This month</small><div class="metric">${tv?'89.2':d.id==='03'?'0':'34.1'} GB</div></div><div><small>LAN today</small><div class="metric">${d.lan} GB</div></div></div>${tv?chart('week',true):'<p class="hint">Daily device history will appear here. Demo chart samples focus on Samsung TV.</p>'}<p class="hint">${tv?'Sample Samsung TV daily history; today’s Internet and LAN totals match this device.':'Usage is estimated.'} No hourly samples are available today.</p>`,'span-8 tablet-full')}
 ${section('Daily quota',`<div class="row">${ring(Math.round(d.used/state.quota*100),'of 5 GB quota')}<div><strong>${d.used} of ${state.quota} GB</strong><p class="hint">${isLive()&&!state.quotaDry?'Enforcing example':'Dry-run · observing'}</p></div></div><div class="policy-trail"><span>${esc(d.name)} → ${d.cat}</span><span>Inherits category → ${state.quota} GB/day</span><span>Monthly: no cap → ${state.quotaAction} ${state.quotaAction==='Throttle'?'512 Kbps':''}</span></div>${button('Edit quota','quota','text-button','tune')}`,'span-4')}
 ${section('Why is this device restricted?',`<p class="hint" style="margin-block-start:0">Claims are persisted intent. Block wins; otherwise the lowest Kbps cap wins. Router observations may differ.</p>${tv&&isLive()?`<div class="detail-claim"><div class="row between"><h3>Daily Television quota</h3>${chip('Applied example','live')}</div><p>512 Kbps · sample retained claim, captured on a prior reading</p><p>Releases at Cairo midnight. This scenario illustrates overlapping claims, not evaluation of the demo clock.</p><div class="actions">${button('Restore quota now','release-quota','outline')}</div></div><div class="detail-claim"><h3>Bedtime throttle · release pending</h3><p>256 Kbps · recorded winner until the Agent releases it</p><p>Sample prior live claim awaiting forced-dry-run cleanup. The demo clock does not reevaluate it.</p>${button('Release rule claim','release-rule','text-button')}</div>`:`<div class="detail-claim"><h3>${tv?'Manual speed override · 512 Kbps':'No automatic claims active'}</h3><p>${tv?'This limit is separate from quota/rule dry-run. Base category policy is 8 Mbps.':'Automatic quotas and rules are in dry-run in this scenario.'}</p>${tv?button('Remove manual override','remove-override','text-button'):''}</div><div class="detail-claim"><h3>Dry-run preview</h3><p>Television quota would throttle at 5 GB. No automatic claim was created.</p>${link('Review firing history','/activity')}</div>`}`,'span-8')}
 ${section('Device settings',`<label class="check-row"><input id="protect-tv" type="checkbox" ${d.protected||state.protectedTV?'checked':''}><span>Protected device<small>Skip automatic throttle and block. Wireless changes can still affect it.</small></span></label><label class="check-row"><input id="lan-only" type="checkbox" ${d.lanOnly?'checked':''}><span>LAN-only device<small>All future traffic counts as LAN, including real Internet use.</small></span></label>${button('Block device','block','danger','block')}<p class="hint">Manual block is a direct router operation. The current product’s protected guard applies to automatic actions.</p>`,'span-4')}
 ${section('Rules & bedtime',`<div class="list-row">${tile('clock')}<div class="grow"><h3>Bedtime throttle</h3><p>22:00–07:00 · 256 Kbps · all days · Cairo</p>${chip('Forced dry-run','dry')}</div>${button('Edit schedule','rule','text-button')}</div><p class="hint">A device schedule is a TimeWindow rule. Person calendars and bonus-time requests need new backend work.</p>`,'span-6')}
 ${section('Recent history',`<p>21:39 · Last router observation saved.</p><p class="hint">20:51 · Came online<br>18:30 · Category speed policy saved<br>Yesterday · Dry-run quota warning at 80%</p>${link('View all activity','/activity')}`,'span-6')}</div>`;
}
function usage(){
 return head('Understand your data','Usage','Internet usage, with local traffic separated.',button('Export period CSV','export','outline','download'))+
 `<div class="toolbar"><div class="segmented" aria-label="Usage period">${['day','week','month'].map(p=>`<button data-period="${p}" class="${state.period===p?'active':''}" aria-pressed="${state.period===p}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('')}</div><span class="muted">${state.period==='day'?'16 October':state.period==='week'?'10–16 October':'1–16 October'} 2026 · Africa/Cairo</span></div><div class="banner info">${icon('leaf')}<p>LAN source responds, but counters are not live-verified. Keep enforcement in dry-run. LAN totals count both endpoints.</p></div><div class="grid">${section('Internet & local traffic',`<div class="stat-grid"><div><small>Internet ${state.period==='day'?'today':state.period==='week'?'this week':'this month'}</small><div class="metric">${state.period==='day'?'8.4':state.period==='week'?'111.6':'214'} GB</div></div><div><small>LAN excluded</small><div class="metric">${state.period==='day'?'24':state.period==='week'?'122':'196'} GB</div></div><div><small>Devices online</small><div class="metric">5 <small>of 6</small></div></div></div>${chart()}<p class="hint">1 GB = 1,000,000,000 bytes. Historical periods may contain unclassified LAN traffic. Day view shows totals; hourly detail is not available.</p>`,'span-8 tablet-full')}
 ${section('A look ahead',`<div class="preview-label">Proposed forecast · example</div><small>300 GB sample ISP plan · cycle starts 1 Oct</small><div class="metric">Around 21 Oct</div><p>At 17.2 GB/day, the remaining 86 GB would last about five days.</p><p class="hint">Uses seven complete valid days. A real forecast stays unavailable while source accuracy is unresolved.</p>${button('Edit ISP budget','budget','text-button','tune')}`,'span-4 forecast')}
 ${section('Top talkers today',consumers(),'span-6')}
 ${section('By category · today',`<div class="consumer"><div class="symbol-tile">${icon('tv')}</div><div><strong>Television</strong><div class="meter"><span style="--fill:100%"></span></div></div><b>4.2 GB</b></div><div class="consumer">${tile('laptop')}<div><strong>Laptop</strong><div class="meter"><span style="--fill:50%"></span></div></div><b>2.1 GB</b></div><div class="consumer">${tile('devices')}<div><strong>Mobile</strong><div class="meter"><span style="--fill:33%"></span></div></div><b>1.4 GB</b></div><p class="hint">Other categories: 0.7 GB Internet. LAN-only server: 0 GB Internet.</p>`,'span-6')}</div>`;
}
const autoTabs = active => `<nav class="section-tabs" aria-label="Automations sections">${[['Overview',''],['Quotas','/quotas'],['Rules','/rules'],['Schedules','/schedules'],['Speed policies','/policies']].map(([t,p])=>link(t,'/automations'+p,active===p?'active':'')).join('')}</nav>`;
function automations(){
 const sub=state.route.split('/')[2]||'';
 let body='';
 if(!sub) body=`<div class="grid">${[['Quotas','usage','Daily & monthly limits','Default, category and device allowances.','quotas','Edit quotas'],['Rules','automations','When this, do that','Five triggers, four actions, clear explanations.','rules','Explore rules'],['Schedules','clock','A quieter bedtime','TimeWindow rules, with a safe return in the morning.','schedules','Set bedtime'],['Speed policies','tune','A fair share of bandwidth','Separate download and upload limits by category.','policies','Manage policies']].map(([t,i,s,p,r,a])=>`<article class="card automation-card span-6">${tile(i)}<div class="eyebrow">${t}</div><h2>${s}</h2><p class="muted">${p}</p>${link(a,'/automations/'+r,'outline','arrow')}</article>`).join('')}</div>`;
 else if(sub==='quotas') body=`<div class="banner info">${icon('shield')}<p>These are per-device quotas. A household ISP budget is separate. Blank cap means no cap; remove an override to inherit.</p></div><div class="grid">${section('Global default',`<div class="row between"><div><div class="metric">5 GB <small>/ day per device</small></div><p class="hint">Notify only · no monthly cap</p></div>${chip('Dry-run','dry')}</div>${button('Edit default','quota-default','outline')}`,'span-6')}${section('Television category',`<div class="row between"><div><div class="metric">${state.quota} GB <small>/ day</small></div><p class="hint">${state.quotaAction} ${state.quotaAction==='Throttle'?'512 Kbps':''} · warns at 80%, 90%</p></div>${chip(state.quotaDry?'Dry-run':'Enforcing example',state.quotaDry?'dry':'live')}</div>${button('Edit quota','quota','button')}`,'span-6')}${section('Effective policy preview',`<label class="field">Device<select><option>Samsung TV</option></select></label><div class="policy-trail" style="margin-block-start:20px"><span>Samsung TV → inherits Television</span><span>${state.quota} GB/day → no monthly cap</span><span>${state.quotaAction} ${state.quotaAction==='Throttle'?'512 Kbps':''} → ${state.quotaDry?'Dry-run':'Enforcing example'}</span></div><p class="hint">A device override replaces the whole matched policy. Explicit no-cap does not inherit a lower scope’s cap.</p>${button('Add device override','quota-device','text-button','add')}`,'span-8')}${section('Safety controls',`<div class="list-row">${tile('shield')}<div><h3>2 protected devices</h3><p>Pixel phone · Jellyfin server</p></div></div><div class="list-row">${tile('leaf')}<div><h3>1 LAN-only device</h3><p>Jellyfin server · future traffic only</p></div></div>${link('Review safety','/settings/safety')}`,'span-4')}</div>`;
 else if(sub==='rules') body=`<div class="banner info">${icon('eye')}<p><strong>Rules are in forced dry-run.</strong> Docker configuration overrides individual flags. Dry-run can still send notifications.</p></div><div class="card"><div class="section-head"><h2>Saved rules</h2>${button('Create rule','rule','button','add')}</div>${[[state.ruleSaved?state.ruleName:'Bedtime throttle','Samsung TV · 22:00–07:00 → 256 Kbps'],['Binge alert','Television · 10 GB/day → Notify']].map(([t,p])=>`<div class="list-row">${tile('automations')}<div class="grow"><h3>${esc(t)}</h3><p>${p}</p>${chip('Enabled')}${chip('Forced dry-run','dry')}</div><div class="actions">${button('Edit','rule','text-button')}${button('Delete','delete-rule','text-button')}</div></div>`).join('')}</div><section class="card" style="margin-block-start:20px"><div class="section-head"><h2>Start with a template</h2><small>Unsaved until you choose Save</small></div><div class="template-grid">${[['Bedtime throttle','22:00–07:00 · 256 Kbps'],['Binge alert','10 GB/day · notification only'],['New device guard','Notify + 256 Kbps · approve via release'],['Household monthly ISP cap warning','Whole-household threshold · notify'],['Idle device cleanup reminder','14 days unseen · reminder, never delete'],['Guest WiFi off at night','01:00–06:00 · guest only, then restore']].map(([t,p])=>`<button class="template" data-template="${t}"><strong>${t}</strong><small>${p}</small></button>`).join('')}</div>${button('Preview last 7 days','historical','text-button','eye')}</section>`;
 else if(sub==='schedules') body=`<div class="grid">${section('Bedtime, with a safe morning',`<div class="row">${tile('clock',true)}<div><div class="metric">22:00 → 07:00</div><p class="hint">Every day · Africa/Cairo · Samsung TV</p></div></div><p style="margin-block:20px">Throttle to 256 Kbps, then release when the window ends.</p>${chip('TimeWindow rule','dry')}${button('Edit bedtime','rule','button')}<p class="hint">Starts and ends on the Agent’s next tick, not exactly at the displayed minute. Per-person calendars need new backend work.</p>`,'span-8')}${section('Keep management reachable',`<p>Protected devices skip automatic throttle and block. Main WiFi cannot be changed by a rule.</p>${link('Safety Center','/settings/safety')}`,'span-4')}</div>`;
 else body=`<div class="card"><div class="section-head"><h2>Category speed policies</h2>${button('Bulk edit','speed','outline','tune')}</div><p class="hint" style="margin-block-start:0">Base speed policies are independent of quota/rule dry-run. Unconfigured categories leave the router alone.</p>${[['Television','8 Mbps ↓ / 2 Mbps ↑','Configured · v3'],['Game console','20 Mbps ↓ / 5 Mbps ↑','Configured · v2'],['Mobile','Unlimited','Not applied'],['IP camera','Unlimited','Not applied']].map(([c,v,s])=>`<div class="list-row"><div class="grow"><h3>${c}</h3><p>${v} · ${s}</p></div>${button('Edit','speed','text-button')}${button('Force reapply','reapply','outline')}</div>`).join('')}<div class="actions">${button('Save all','save-policies','button')}${button('Sync all','reapply','outline')}</div></div>`;
 return head('Keep it fair','Automations','Simple defaults. Clear causes. You stay in control.')+autoTabs(sub?'/'+sub:'')+body;
}
function activity(){
 const inbox=state.route.endsWith('/inbox');
 const events=[{time:'21:39',type:'system',icon:'router',title:'Agent tick completed',body:'5 online devices observed. Rules ran in forced dry-run.',chip:'System',kind:''},{time:'21:36',type:'quota',icon:'usage',title:'Samsung TV reached 80% of its quota',body:'4.2 of 5 GB Internet today. Dry-run: would throttle at 5 GB.',chip:'Dry-run',kind:'dry'},{time:'21:12',type:'rule',icon:'automations',title:'Binge alert evaluated',body:'Television category · below 10 GB/day. No action taken.',chip:'Rule',kind:''},{time:'20:51',type:'device',icon:'devices',title:'Pixel phone came online',body:'192.168.1.31 · WiFi 5 GHz · protected device.',chip:'Device',kind:'ok'},{time:'19:12',type:'notification',icon:'bell',title:'Notification accepted by push service',body:'Does not prove phone display. This is a sample delivery attempt.',chip:'Transport log',kind:''}];
 const list=events.filter(e=>state.activity==='all'||e.type===state.activity);
 return head('Know what happened',inbox?'Notification inbox':'Activity',inbox?'A proposed durable inbox, distinct from push delivery attempts.':'A clear timeline of your network. Times in Africa/Cairo.')+
 `<nav class="section-tabs" aria-label="Activity views">${link('Timeline','/activity',!inbox?'active':'')}${link('Inbox · 2','/activity/inbox',inbox?'active':'')}</nav>`+
 (inbox?`<div class="banner info">${icon('bell')}<p>Unread state and in-app action buttons need new backend work. Existing push actions use scoped, expiring single-use tokens.</p></div><div class="card"><div class="list-row">${tile('usage')}<div class="grow"><h3>TV quota warning</h3><p>Sample live quota action for today’s period only.</p><div class="actions">${button('+1 GB today','bonus','tonal')}${button('Restore now','release-quota','outline')}${button('Mark read','mark-read','text-button')}</div></div></div><div class="list-row">${tile('devices')}<div class="grow"><h3>New device joined</h3><p>Review its identity before trusting it.</p>${link('Review devices','/devices')}</div></div></div>`:
 `<div class="toolbar"><label class="field">Show events<select id="activity-filter">${[['all','Everything'],['quota','Quotas'],['rule','Rules'],['device','Devices'],['system','System'],['notification','Notifications']].map(([v,t])=>`<option value="${v}" ${state.activity===v?'selected':''}>${t}</option>`).join('')}</select></label><span class="muted">Friday, 16 October 2026</span></div><div class="card"><ol class="timeline">${list.map(e=>`<li><time>${e.time}</time>${tile(e.icon)}<div><div class="row between"><h3>${e.title}</h3>${chip(e.chip,e.kind)}</div><p>${e.body}</p>${link(e.type==='quota'?'Why / view device':'View source',e.type==='quota'?'/devices/02-00-00-00-00-02':e.type==='rule'?'/automations/rules':e.type==='device'?'/devices':'/settings/health')}</div></li>`).join('')}</ol></div>`);
}
const settingsItems=[['Overview','','settings'],['Router','router','router'],['Wireless','wireless','wifi'],['Notifications','notifications','bell'],['Safety Center','safety','shield'],['Security','security','lock'],['LAN source','traffic','leaf'],['HTTPS / Install','app','devices'],['System health','health','activity'],['Backup','backup','cloud'],['About / appearance','about','tune']];
function settings(){
 const sub=state.route.split('/')[2]||'';let body='';
 if(!sub) body=`<div class="grid">${section('Your household controls',`<p>Connect and maintain your network, keep alerts useful, and make safety visible.</p>${settingsItems.slice(1).map(([t,p,i])=>`<a class="list-row" style="text-decoration:none;color:inherit" href="#/settings/${p}">${tile(i)}<span class="grow"><strong>${t}</strong></span>${icon('arrow')}</a>`).join('')}`,'span-12')}</div>`;
 else if(sub==='notifications') body=`<div class="stack">${section('Alerts on this device',`<div class="row between"><div class="row">${tile('bell')}<div><h3>Pixel phone · sample browser</h3><p class="hint">${state.notifications?'Subscribed in demo':'Not subscribed in demo'}</p></div></div>${chip('Mock browser state','dry')}</div><dl class="key-values"><dt>Secure context</dt><dd>HTTPS example (not this local file)</dd><dt>Push support</dt><dd>Android Chrome example</dd><dt>Permission</dt><dd>${state.notifications?'Granted · simulated':'Not requested'}</dd></dl><label class="field">Device label<input value="My Pixel" maxlength="80"></label><div class="actions" style="margin-block-start:20px">${button(state.notifications?'Disable here':'Enable on this device','subscribe','button','bell')}${button('Send test to all','test-push','outline')}</div><p class="hint">The prototype never requests OS permission. Real push requires trusted HTTPS; installation is optional. Remove server registration differs from browser unsubscribe.</p>`)}${section('Quiet hours',`<div class="preview-label">Proposed editable settings</div><div class="form-grid"><label class="field">From<input type="time" value="23:00"></label><label class="field">Until<input type="time" value="07:00"></label></div><p class="hint">Africa/Cairo. Only eligible Warning / DryRun quota kinds are silenced and dropped. Exceeded, Applied, Reverted and Protected skips bypass, including dry-run Exceeded. Current UI displays configuration only.</p>${button('Preview saved preference','quiet-save','outline')}`)}${section('Event preferences',`<div class="preview-label">New backend required</div>${['Quota warnings','Rule dry-run results','New device joined','Agent / source health'].map(t=>`<label class="check-row"><input type="checkbox" checked><span>${t}</span></label>`).join('')}<p class="hint">These demonstration switches do not change production event delivery.</p>`)}${section('Registered devices',`<div class="list-row"><div class="grow"><h3>My Pixel</h3><p>Sample registration · last success 19:12 · failures 0</p></div>${button('Remove registration','remove-subscription','text-button')}</div><p class="hint">Test sends go to all registrations and bypass quiet hours/dedupe. Acceptance does not prove phone display.</p>`)}</div>`;
 else if(sub==='safety') body=`<div class="stack">${section('Observe first. Enforce with evidence.',`<div class="row" style="margin-block-end:20px">${tile('shield',true)}<div>${chip(isLive()?'Enforcing example':'Quotas: Dry-run',isLive()?'live':'dry')} ${chip('Rules: Forced dry-run','dry')}<p class="hint">Manual controls and base speed policies operate separately.</p></div></div><p>Dry-run evaluates and logs what would happen. It can still notify, but does not create automatic router restrictions.</p><p class="hint">Docker forces rules dry-run by default. The real app must confirm Agent effective config before declaring a mode active.</p>`)}${section('Before you graduate',`<div class="preview-label">Evidence checklist · example only</div>${[['Compare router units and resets','Several days of Internet observations, not a single matching sample.'],['Verify the Jellyfin → TV path','Complete LAN counters and YouTube experiment on Proxmox.'],['Protect your management devices','Pixel phone and server; protection does not prevent wireless changes.'],['Check Agent health and Android alerts','Fresh ticks, phone display and action response.'],['Try a reversible restriction and release','One policy first; understand other active claims.']].map(([t,s])=>`<label class="check-row"><input type="checkbox" class="safety-check"><span>${t}<small>${s}</small></span></label>`).join('')}<div class="banner info" style="margin-block-start:16px">${icon('lock')}<p>This prototype cannot verify those checks or change Docker mode. Keep real enforcement off pending live verification.</p></div>${button('Review graduation plan','graduate','button')}`)}${section('Protected devices',`<div class="list-row">${tile('devices')}<div><h3>Pixel phone</h3><p>Management device</p></div></div><div class="list-row">${tile('server')}<div><h3>Jellyfin server</h3><p>Protected · LAN-only</p></div></div>${link('Manage on device pages','/devices')}`)}</div>`;
 else if(sub==='router')body=section('Router connection',`<div class="form-stack"><label class="field">Provider<select><option>TP-Link · Archer AX53</option><option disabled>Other providers require an adapter</option></select></label><label class="field">Host<input value="192.168.1.1"></label><label class="field">Router password<input type="password" placeholder="Leave blank to keep saved password" autocomplete="off"></label><label class="check-row"><input type="checkbox"><span>Use HTTPS to the router<small>Separate from dashboard HTTPS and phone access.</small></span></label><div class="actions">${button('Test connection','test-router','outline')}${button('Save connection','save-router','button')}</div><p class="hint">Test currently logs into the router from Web and may contend with the Agent’s single session. Password is encrypted at rest in the real app.</p></div>`);
 else if(sub==='wireless')body=`<div class="stack">${section('Guest networks',`<div class="row between"><div><h3>Home Guest · 5 GHz</h3><p class="hint">guest-5g · WPA2 · follows main radio</p></div>${chip(state.guest?'On':'Off',state.guest?'ok':'')}</div><div class="actions">${button('Edit guest network','wireless','outline')}${button(state.guest?'Turn off':'Turn on','guest','tonal','wifi')}</div><p class="hint">Direct Web write with returned readback. Guest SSID, password and on/off are implemented.</p>`)}${section('IoT network',`<h3>Home IoT · 2.4 GHz</h3><p class="hint">SSID / enable edits supported. Password, channel, width and TX-power changes unavailable.</p>${button('View editable fields','iot','outline')}`)}${section('Main WiFi · read-only',`<details><summary>View main network / danger zone</summary><p>Home · 2.4 GHz and 5 GHz</p><p class="hint">Main writes and radio coupling are unverified. Extra confirmation does not make an unsupported operation safe. Main WiFi is never a rule action.</p><button disabled class="danger">Main WiFi edit unavailable</button></details>`)}</div>`;
 else if(sub==='traffic')body=`<div class="stack">${section('LAN traffic source',`<div class="row">${tile('leaf')}${chip('Responding · sample','ok')}${chip('Accuracy unverified','warning')}</div><dl class="key-values"><dt>Last read</dt><dd>16 Oct · 21:39 Cairo</dd><dt>Source</dt><dd>Proxmox bridge exporter</dd><dt>Coverage</dt><dd>Configured IPv4 pairs only</dd><dt>Unavailable fallback</dt><dd>All router bytes counted</dd></dl><p>Local streams are counted at both endpoints. Successful HTTP reads cannot prove WiFi TV traffic crosses the bridge or that router units match.</p><p class="hint">LAN-only Jellyfin flag hides all its future Internet use too; it does not fix the TV’s count or reclassify history. Exporter secrets are never shown here.</p><a class="text-button" href="../../lan-traffic-exclusion.md">Open counter verification guide ↗</a>`)}${section('Known limits',`<p>First flow observation is a baseline. Outages can skew future subtraction; carry is capped at 1 GB/device. Old totals are not retroactively fixed. Keep enforcement in dry-run.</p>`)}</div>`;
 else if(sub==='health')body=`<div class="stack">${section('Agent & system',`<div class="preview-label">New health backend required</div><dl class="key-values"><dt>Agent heartbeat</dt><dd>${offline()?'No fresh router observation':'21:39 · sample'}</dd><dt>Tick duration</dt><dd>2.4 s · sample</dd><dt>Configured interval</dt><dd>180 s</dd><dt>Shared database</dt><dd>18.6 MB · sample</dd><dt>Agent / Web</dt><dd>Development build · example</dd><dt>Firmware / CPU / uptime</dt><dd>No live read · CPU/uptime unsupported</dd></dl><p class="hint">Health must be persisted by Agent, not inferred from Web uptime. A stopped Agent needs an external watchdog to send a down alert.</p>`)}${section('Danger zone',`<p>Reboot disconnects the whole household. The current router endpoint still needs live verification.</p>${button('Reboot router','reboot','danger','refresh')}`)}</div>`;
 else if(sub==='security')body=section('An administrator login is needed',`<div class="banner error">${icon('lock')}<p>The current dashboard has no authentication. Trusted HTTPS and Tailscale do not add a dashboard login.</p></div><p>Proposed: one administrator password and a server session, with rate limits, idle expiry, revocation and a local recovery path. Read-only family access can follow.</p><p class="hint">No mock password is collected here. PIN-only network access is not recommended. Authentication implementation needs separate security review.</p>${button('Review proposed login flow','auth-preview','outline')}`);
 else if(sub==='app')body=section('HTTPS & your home screen',`<div class="row">${tile('devices',true)}<div><h3>NetPilot on Android</h3><p class="hint">Install is optional for Web Push.</p></div></div><p style="margin-block-start:24px">Use the trusted HTTPS origin from Tailscale Serve, or the LAN Caddy option with a trusted CA. A local file preview cannot test service workers or phone delivery.</p><div class="actions">${button('Preview install guidance','install','button')}${link('Notification settings','/settings/notifications','outline')}</div><p class="hint">Proposed shortcuts open Home, Devices, Usage and a Pause TV confirmation. Offline shell cannot manage a Blazor Server app without a connection.</p><a class="text-button" href="../../https-access.md">HTTPS setup guide ↗</a>`);
 else if(sub==='backup')body=section('A recovery plan for your household',`<div class="preview-label">New backend required</div><p>Back up a coherent database snapshot and the shared Data Protection key ring together. Full backups need encryption; ordinary config exports must be redacted.</p><div class="actions" style="margin-block-start:24px">${button('Preview backup plan','backup','outline')}${button('Preview restore plan','restore-backup','text-button')}</div><p class="hint">No file is created by these controls. Restore must coordinate Agent/Web, validate version/checksum, preserve a safety copy and be rehearsed on an isolated volume.</p>`);
 else body=section('Made for your household',`<h3>NetPilot · design preview</h3><p class="hint">Material 3 · native Razor + token CSS · single router. Production licence currently TBD.</p><div class="form-stack" style="margin-block-start:24px"><p>Use the footer controls to choose System / Light / Dark, Teal / Violet and an RTL layout preview.</p><p class="hint">Arabic translation, multi-router switching, Home Assistant REST integration and backup controls require their own implementation tasks. No MQTT change is proposed.</p></div>`);
 return head('Your preferences','Settings','A dependable home network starts with clear controls.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${settingsItems.map(([t,p,i])=>link(t,'/settings'+(p?'/'+p:''),sub===p?'active':'',i)).join('')}</nav><div>${body}</div></div>`;
}
function setup(){
 const step=Math.max(1,Math.min(6,Number(state.route.split('/')[2])||1));
 const contents=[
 ['router','Connect your router','Start with the router already in your home.',`<div class="form-stack"><label class="field">Provider<select><option>TP-Link Archer AX53</option></select></label><label class="field">Router address<input value="192.168.1.1" aria-describedby="router-help"></label><label class="field">Router password<input type="password" placeholder="Not collected in this preview" autocomplete="off" disabled></label><p class="hint" id="router-help">The real app encrypts credentials at rest. Test currently connects directly from Web; the Agent owns automatic enforcement.</p>${button(state.setupTested?'Demo test passed ✓':'Test connection (demo)','setup-test','outline')}</div>`],
 ['devices','Meet your devices','Six sample devices, ready to review.',devices.map(d=>`<div class="list-row">${tile(d.type)}<div class="grow"><h3>${d.name}</h3><p>${d.medium}</p></div>${chip(d.online?'Online':'Offline',d.online?'ok':'')}</div>`).join('')],
 ['tune','Make the names familiar','Keep the reported categories, and protect your management devices.',`<div class="form-stack">${devices.slice(0,3).map(d=>`<label class="field">${d.name}<select><option>${d.cat}</option><option>Uncategorized</option></select></label>`).join('')}<label class="check-row"><input type="checkbox" checked><span>Protect Pixel phone and Jellyfin server<small>Automatic throttle and block will skip them.</small></span></label></div>`],
 ['shield','Start by observing','A safe default, with no automatic restrictions.',`<div class="row">${ring(0,'used at setup')}<div><div class="metric">5 GB</div><p>per device / day</p>${chip('Dry-run','dry')}</div></div><p>Notify only. No monthly cap. This is a default per-device quota, not a household limit.</p><p class="hint">Compare a few days of usage and verify LAN exclusion before considering enforcement.</p>`],
 ['bell','Take useful alerts with you','Optional notifications, and an optional home-screen app.',`<div class="banner info">${icon('lock')}<p>Trusted HTTPS is required. This local prototype does not request browser permissions.</p></div><div class="actions">${button('Try notification setup','setup-notifications','button')}${button('Install guidance','install','outline')}</div><p class="hint">You can skip this step. Android Chrome supports push without installing the app.</p>`],
 ['check','You’re ready to observe','Nothing automatic will throttle or block yet.',`<div class="row">${tile('shield',true)}${chip('Dry-run first','dry')}</div><p style="margin-block-start:24px">Your next steps: review device categories, compare Internet usage and complete the LAN counter checks.</p>${link('Visit Safety Center','/settings/safety','text-button','arrow')}`]
 ][step-1];
 return head('Welcome to NetPilot','A calmer home network.','Setup at your pace. No router operations run in this preview.')+`<div class="setup-wrap"><div class="step-track" aria-label="Step ${step} of 6">${[1,2,3,4,5,6].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><section class="card"><div class="setup-hero"><div class="setup-art">${icon(contents[0])}</div><div><div class="eyebrow">Step ${step} of 6</div><h2>${contents[1]}</h2><p class="muted">${contents[2]}</p></div></div>${contents[3]}<hr class="panel-divider"><div class="row between">${step>1?link('Back','/setup/'+(step-1),'outline','back'):link('Explore demo','/','text-button')}${step<6?link(step===5?'Continue / skip':'Continue','/setup/'+(step+1),'button','arrow'):link('Open Home','/','button','arrow')}</div></section></div>`;
}
function empty(title,copy,label,href){return `<div class="card empty-state">${tile('wifi')}<h1>${title}</h1><p>${copy}</p>${link(label,href,'button')}</div>`;}
function render(focus = true){
 state.route=location.hash.slice(1)||'/';
 if(state.route==='#main')state.route='/';
 const top=state.route.split('/')[1]||'home';
 const navs=[['home','Home','/'],['devices','Devices','/devices'],['usage','Usage','/usage'],['automations','Automations','/automations'],['activity','Activity','/activity']];
 $('#nav').innerHTML=navs.map(([i,t,r])=>`<a class="nav-item" href="#${r}" ${top===i?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('');
 $('#mode-strip').classList.toggle('live',isLive());
 $('#mode-strip').innerHTML=`<span class="mode-main">${icon('shield')}<span>Quotas: ${isLive()?'Enforcing example':'Dry-run'}</span><span aria-hidden="true">·</span><span>Rules: Forced dry-run</span></span><small>Safety Center ${icon('arrow')}</small>`;
 let content='';
 if(top==='home')content=home();else if(top==='devices')content=state.route==='/devices'?devicesPage():detail();else if(top==='usage')content=usage();else if(top==='automations')content=automations();else if(top==='activity')content=activity();else if(top==='settings')content=settings();else if(top==='setup')content=setup();else content=empty('Page not in this prototype','Use the primary navigation to explore the proposed dashboard.','Open Home','/');
 let stateBanner='';
 if(offline())stateBanner=`<div class="banner">${icon('wifi')}<div><strong>Router unavailable · last read 20:51</strong><p>Saved observations are stale. Direct router commands are unavailable. Data-only edits can wait for the Agent.</p></div></div>`;
 if(state.scenario==='error')stateBanner=`<div class="banner error" role="alert">${icon('warning')}<div><strong>Couldn’t refresh this view</strong><p>Showing the last saved sample. Your edits are preserved.</p>${button('Retry demo read','retry','outline')}</div></div>`;
 if(state.scenario==='loading')content=head('Loading sample data','Getting your network ready','Layout remains stable while data loads.')+`<div class="skeleton-wrap" aria-busy="true"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div>`;
 if(state.scenario==='empty')content=empty(top==='devices'?'No devices discovered yet':top==='activity'?'Nothing to report yet':'Your network story starts here',top==='activity'?'Events appear after your Agent starts observing.':'Connect a router, discover devices and start in dry-run.','Start setup','/setup/1');
 $('#main').innerHTML=stateBanner+receipt()+content;
 if($('#device-results'))renderDevices();
 if(offline())$$('[data-action]').filter(e=>['block','unblock','guest','wireless','iot','reboot','reapply','refresh-router','test-router'].includes(e.dataset.action)).forEach(e=>{e.disabled=true;e.title='Router unavailable. Try again after a fresh reading.';});
 const title=$('h1', $('#main'));document.title=`${title?title.textContent:'NetPilot'} · NetPilot design preview`;
 if(focus){$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
}
function quotaEditor(kind='category'){
 const label=kind==='default'?'Default per-device quota':kind==='device'?'Samsung TV override':'Television quota';
 openSheet(label,`<form id="quota-form" class="form-stack"><div class="preview-label">Local demo editor · no router write</div><div class="form-grid"><label class="field">Daily cap · decimal GB<input id="quota-cap" name="cap" type="number" min="0.001" step="any" value="${state.quota}" required aria-describedby="cap-help"></label><label class="field">Monthly cap · GB<input name="monthly" type="number" min="0.001" step="any" placeholder="No cap"></label></div><label class="field">Visual cap shortcut<input id="quota-range" type="range" min="1" max="30" value="${state.quota}" aria-label="Daily cap shortcut in GB"></label><p class="hint" id="cap-help">Blank monthly cap means no monthly cap. Remove an override to inherit. 1 GB = 1,000,000,000 bytes.</p><label class="field">When exceeded<select id="quota-action" name="action">${['Notify only','Throttle','Block'].map(t=>`<option ${state.quotaAction===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Symmetric throttle · Kbps<input name="rate" id="quota-rate" type="number" min="1" step="1" value="512"></label><label class="field">Warn at percentages<input name="warnings" value="80,90" aria-describedby="warn-help"></label><small id="warn-help">Sorted, distinct 1–99. Blank disables warnings.</small><label class="check-row"><input type="checkbox" name="dry" ${state.quotaDry?'checked':''}><span>Dry-run<small>Evaluate, log and notify. No automatic router restriction.</small></span></label><label class="check-row"><input type="checkbox" name="exempt"><span>Exempt from quota evaluation</span></label><div class="policy-trail" id="quota-preview">Samsung TV → ${kind==='device'?'device override':'Television'} → ${state.quota} GB/day → ${state.quotaAction}</div><p id="quota-error" class="error-text" role="alert"></p></form>`,`<p class="hint">${nextTick}</p>${button('Cancel','close-editor','outline')}${button('Remove override','remove-quota','text-button')}<button class="button" type="submit" form="quota-form">Save quota</button>`);
 $('#quota-rate').disabled=state.quotaAction!=='Throttle';
}
function ruleEditor(template){
 if(template){state.ruleName=template;state.ruleStep=1;state.ruleTrigger=template==='Binge alert'?'Device usage over':template==='New device guard'?'New device joined':template==='Household monthly ISP cap warning'?'Household usage over':template==='Idle device cleanup reminder'?'Device idle':'Time window';state.ruleAction=template==='Guest WiFi off at night'?'Set guest/IoT WiFi':/alert|warning|reminder/.test(template)?'Notify':'Throttle';}
 const s=state.ruleStep;
 const steps=['Who & name','When','Do what','Revert & repeat','Review'];
 let body='';
 if(s===1)body=`<label class="field">Rule name<input id="rule-name" maxlength="80" value="${esc(state.ruleName)}" required></label><label class="field">Scope<select id="rule-scope">${['Samsung TV','Television category','All devices','Selected devices'].map(x=>`<option ${state.ruleScope===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="hint">Selected device lists and missing stored MACs must remain editable in production. This focused prototype uses Samsung TV as its sample target.</p>`;
 if(s===2)body=`<label class="field">Trigger<select id="rule-trigger">${['Device usage over','Household usage over','Time window','New device joined','Device idle'].map(t=>`<option ${state.ruleTrigger===t?'selected':''}>${t}</option>`).join('')}</select></label><div id="trigger-fields">${triggerFields()}</div>`;
 if(s===3)body=`<label class="field">Action<select id="rule-action">${['Notify','Throttle','Block','Set guest/IoT WiFi'].map(x=>`<option ${state.ruleAction===x?'selected':''}>${x}</option>`).join('')}</select></label><div id="action-fields">${actionFields()}</div><p class="hint">Multiple actions are supported in the existing product. This prototype walks through one; the specification retains Add/remove action.</p><div class="banner info">${icon('shield')}<p>Protected devices skip throttle/block. Main WiFi is never selectable.</p></div>`;
 if(s===4)body=`<label class="field">Release restriction<select id="rule-revert">${['Manual release only','At period end','After a delay',...(state.ruleTrigger==='Time window'?['When time window ends']:[])].map(x=>`<option ${state.ruleRevert===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Revert delay · minutes<input type="number" min="1" value="60"></label><label class="field">Cooldown · minutes<input id="rule-cooldown" type="number" min="0" value="${state.ruleCooldown}"></label><label class="field">Once per<select id="rule-once">${['None','Day','Month'].map(x=>`<option ${state.ruleOnce===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="hint">Day/Month replaces cooldown repeat behavior. Active-firing and episode guards still apply. Nonusage period-end means midnight.</p>`;
 if(s===5)body=`<div class="policy-trail"><span><strong>${esc(state.ruleName)}</strong></span><span>For ${esc(state.ruleScope)}</span><span>When: ${esc(state.ruleTrigger)}</span><span>Then: ${esc(state.ruleAction)} ${state.ruleAction==='Throttle'?state.ruleRate+' Kbps':''}</span><span>Revert: ${esc(state.ruleRevert)}</span><span>Once per ${state.ruleOnce}; cooldown ${state.ruleCooldown} minutes</span></div>${chip('Dry-run on','dry')}${chip('Deployment forces dry-run','dry')}<p class="hint">Static preview: targets Samsung TV; management devices are protected. Historical replay is not implemented. This does not evaluate actual recent traffic.</p>`;
 openSheet(`Create rule · ${s}/5`,`<div class="step-track">${steps.map((_,i)=>`<span class="${i<s?'done':''}"></span>`).join('')}</div><p class="eyebrow" style="margin-block-end:20px">${steps[s-1]}</p><div class="form-stack">${body}<p id="rule-error" class="error-text" role="alert"></p></div>`,`<p class="hint">Africa/Cairo. ${nextTick}</p>${s>1?button('Back','rule-back','outline'):button('Cancel','close-editor','outline')}${button(s===5?'Save in dry-run':'Continue',s===5?'save-rule':'rule-next','button','arrow')}`);
}
function triggerFields(){const t=state.ruleTrigger;return t==='Time window'?`<div class="form-grid"><label class="field">Start<input type="time" value="22:00"></label><label class="field">End<input type="time" value="07:00"></label></div><fieldset style="border:0;padding:16px 0"><legend>Days the window starts</legend><div class="weekday-row">${['Sa','Su','Mo','Tu','We','Th','Fr'].map(d=>`<label><input type="checkbox" checked>${d}</label>`).join('')}</div></fieldset><p class="hint">Overnight window belongs to its start day · Africa/Cairo. No exact-minute guarantee.</p>`:t.includes('usage')?`<div class="form-grid"><label class="field">Period<select><option>Day</option><option>Month</option></select></label><label class="field">Internet threshold · GB<input type="number" min="0.001" step="any" value="10"></label></div><p class="hint">${t.startsWith('Household')?'Usage sums the entire household. Scope chooses action targets.':'Positive decimal GB; up to nine decimal places.'}</p>`:t==='Device idle'?`<label class="field">Days since last seen<input type="number" min="1" value="14"></label>`:`<p class="hint">Only devices first discovered after rule creation count as new.</p>`;}
function actionFields(){return state.ruleAction==='Throttle'?`<label class="field">Upload + download · Kbps<input id="rule-rate" type="number" min="1" value="${state.ruleRate}"></label>`:state.ruleAction==='Notify'?`<label class="field">Title<input value="{rule}: {device}"></label><label class="field">Body<textarea>{device} has used {used} bytes of {cap} bytes.</textarea></label><p class="hint">Current placeholders use raw bytes. Preview must not silently convert only some outputs.</p>`:state.ruleAction==='Set guest/IoT WiFi'?`<label class="field">Network<select><option>guest-5g · available example</option><option>iot-2.4g · available example</option></select></label><label class="field">Set state<select><option>Off</option><option>On</option></select></label>`:`<p class="hint">Block outranks every throttle claim. Releasing another owner may leave this block active.</p>`;}
function actionSheet(kind){
 const selected = state.selected.size ? devices.filter(d=>state.selected.has(d.id)) : [devices[1]];
 const targets=selected.map(d=>d.name).join(', ');
 const duration=kind==='pause'?`<label class="field">Duration<select id="action-duration"><option>15 minutes</option><option selected>30 minutes</option><option>60 minutes</option></select></label>`:'';
 openSheet(kind==='bonus'?'Add a little more data':kind==='block'?'Block a device':'Pause internet',`<div class="form-stack"><div class="preview-label">Proposed command flow · local simulation</div><label class="field">Target<select id="quick-target"><option>${esc(targets)}</option><option>Television category · 1 device</option></select></label>${duration}${kind==='bonus'?`<div class="form-grid"><label class="field">Bonus · decimal GB<input type="number" id="bonus-amount" value="1" min="0.001" step="any"></label><label class="field">Period<select><option>Today · 16 Oct</option><option>This month · Oct</option></select></label></div><p class="hint">Existing notification actions add exactly 1 GB to their named period. A general dashboard bonus editor needs new backend work.</p>`:''}<div class="banner ${kind==='block'?'error':'info'}">${icon(kind==='block'?'warning':'shield')}<p>${kind==='block'?'Manual block is currently a direct Web command, separate from dry-run. Router block-list readback is unavailable.':kind==='pause'?'Protected targets are skipped. A temporary expiring claim preserves other limits. This backend does not exist yet.':'Bonus daily data does not increase the monthly allowance. Other claims may still restrict this device.'}</p></div><p class="hint">${kind==='block'?'Command accepted does not prove observed blocked state.':nextTick}</p></div>`,`${button('Cancel','close-editor','outline')}${button(kind==='bonus'?'Add bonus':kind==='block'?'Review block':'Review pause','confirm-'+kind,kind==='block'?'danger':'button')}`);
}
function saveRuleFields(){
 if($('#rule-name'))state.ruleName=$('#rule-name').value.trim();
 if($('#rule-scope'))state.ruleScope=$('#rule-scope').value;
 if($('#rule-trigger'))state.ruleTrigger=$('#rule-trigger').value;
 if($('#rule-action'))state.ruleAction=$('#rule-action').value;
 if($('#rule-rate'))state.ruleRate=Number($('#rule-rate').value);
 if($('#rule-revert'))state.ruleRevert=$('#rule-revert').value;
 if($('#rule-cooldown'))state.ruleCooldown=Number($('#rule-cooldown').value);
 if($('#rule-once'))state.ruleOnce=$('#rule-once').value;
}
function handleAction(action){
 const actions={
 'theme':()=>setTheme(state.theme==='system'?'dark':state.theme==='dark'?'light':'system'),
 'rtl':()=>{document.documentElement.dir=document.documentElement.dir==='rtl'?'ltr':'rtl';toast('Layout direction changed. Arabic translation is a separate implementation task.');},
 'search':()=>{lastOpener=document.activeElement;$('#search-dialog').showModal();$('#global-search').value='';renderSearch('');$('#global-search').focus();},
 'close-search':()=>$('#search-dialog').close(),
 'close-editor':()=>closeSheet(), 'cancel-confirm':()=>$('#confirm').close(),
 'accept-confirm':()=>{const fn=confirmCallback;$('#confirm').close();confirmCallback=null;if(fn)fn();},
 'dismiss-toast':()=>{$('#snackbar').hidden=true;},'undo':()=>{const fn=undoCallback;undoCallback=null;$('#snackbar').hidden=true;if(fn)fn();},
 'pause':()=>actionSheet('pause'),'bonus':()=>actionSheet('bonus'),'block':()=>actionSheet('block'),
 'confirm-pause':()=>confirmDialog('Pause this target?',`${nextTick} Protected devices are skipped. Other restrictions remain. This only simulates the proposed command.`, 'Request pause',()=>{closeSheet(true);enqueue('Temporary pause requested · 30 minutes');}),
 'confirm-bonus':()=>{const amount=Number($('#bonus-amount').value);if(!Number.isFinite(amount)||amount<=0){$('#bonus-amount').setCustomValidity('Enter a positive number of GB.');$('#bonus-amount').reportValidity();return;}closeSheet(true);enqueue(`${amount} GB bonus for named period`);},
 'confirm-block':()=>confirmDialog('Block Samsung TV?', 'Direct Web command in the current product. Dry-run does not apply to manual block. The router cannot verify its block list. This is a demo only.', 'Send demo block',()=>{closeSheet(true);toast('Demo block command accepted; recorded state, not verified router state.');}),
 'unblock':()=>confirmDialog('Unblock PS5?', 'This is currently a direct Web command. Other automatic claims may restrict it again. No real router command will be sent.', 'Send demo unblock',()=>toast('Demo unblock command accepted. Other claims still need review.')),
 'why':()=>{location.hash='/devices/02-00-00-00-00-02';},
 'quota':()=>quotaEditor(),'quota-default':()=>quotaEditor('default'),'quota-device':()=>quotaEditor('device'),
 'remove-quota':()=>confirmDialog('Remove this override?', `Samsung TV would inherit the default 5 GB/day Notify-only quota. ${nextTick}`,'Remove override',()=>{const old=state.quota;closeSheet(true);enqueue('Override removal requested');toast('Demo override removed. Awaiting Agent.',()=>{state.quota=old;enqueue('Undo override removal requested');});}),
 'release-quota':()=>confirmDialog('Restore this quota claim?', `Suppress this quota action for the named period. Other daily/monthly/rule claims can remain. ${nextTick}`,'Request restore',()=>enqueue('Quota restore requested; other claims may remain')),
 'release-rule':()=>confirmDialog('Release Bedtime throttle?', `Other quota or base limits can remain. Usage rules can fire again after repeat guards expire. ${nextTick}`,'Request release',()=>enqueue('Bedtime claim release requested')),
 'remove-override':()=>confirmDialog('Remove manual speed override?', `The 8 Mbps category policy will apply, subject to other claims. ${nextTick}`,'Remove override',()=>enqueue('Manual override removal requested')),
 'rule':()=>{state.ruleStep=1;ruleEditor();},
 'rule-next':()=>{saveRuleFields();const invalid=$$('input', $('#editor')).find(e=>!e.checkValidity());if(!state.ruleName||invalid){$('#rule-error').textContent='Check the name and positive values before continuing.';if(invalid)invalid.reportValidity();return;}state.ruleStep=Math.min(5,state.ruleStep+1);ruleEditor();},
 'rule-back':()=>{saveRuleFields();state.ruleStep=Math.max(1,state.ruleStep-1);ruleEditor();},
 'save-rule':()=>{state.ruleSaved=true;closeSheet(true);enqueue('Rule saved in dry-run');},
 'delete-rule':()=>confirmDialog('Delete this rule?',`Active effects release on the Agent’s next tick (about 3 min). Other owners may still restrict devices.`,'Delete rule',()=>{enqueue('Rule deletion requested');toast('Demo rule deletion queued.',()=>enqueue('Undo rule deletion requested'));}),
 'historical':()=>openSheet('What can a preview tell you?',`<p>Daily usage history can support coarse daily threshold estimates. Exact last-seven-days simulation cannot reconstruct joins, idle episodes, time-window actions or WiFi state today.</p><p class="hint">The proposed backend must retain event snapshots and clearly label supported triggers. No replay was run here.</p>`,button('Got it','close-editor','button')),
 'tick':()=>{if(!state.pending.length){toast('No pending demo changes. Save a quota or request a release first.');return;}state.applied.push(...state.pending);state.pending=[];render(false);toast('Simulated Agent confirmation. No real application or router was contacted.');},
 'guest':()=>confirmDialog(state.guest?'Turn guest WiFi off?':'Turn guest WiFi on?', 'Current guest toggle writes directly from Web and reads back state. Guest clients may disconnect. Main WiFi stays unavailable to rules. This is a simulation.', 'Confirm demo change',()=>{if($('#editor').open)closeSheet(true);state.guest=!state.guest;render(false);toast('Demo guest network readback received.');}),
 'wireless':()=>openSheet('Guest WiFi',`<div class="form-stack"><label class="field">SSID<input value="Home Guest"></label><label class="field">New password<input type="password" placeholder="Leave blank to preserve" autocomplete="off"></label><label class="check-row"><input type="checkbox" checked><span>Enabled</span></label><p class="hint">Direct Web write + returned readback. This prototype never saves credentials.</p></div>`,button('Cancel','close-editor','outline')+button('Review change','guest','button')),
 'iot':()=>openSheet('IoT WiFi',`<label class="field">SSID<input value="Home IoT"></label><p class="hint">SSID and on/off supported. Password, radio edits and coupling remain unsupported/unverified.</p>`,button('Close','close-editor','button')),
 'subscribe':()=>{state.notifications=!state.notifications;render(false);toast(state.notifications?'Demo subscription enabled. No browser permission was requested.':'Demo subscription disabled.');},
 'test-push':()=>toast('Sample result: accepted by push service for My Pixel. Phone display unverified; no real push sent.'),
 'quiet-save':()=>toast('Preference preview only. Editing shared quiet hours needs new backend work.'),
 'remove-subscription':()=>confirmDialog('Remove My Pixel registration?','Removing the server record does not unsubscribe the browser. It can register again.','Remove',()=>toast('Demo server registration removal reviewed.')),
 'mark-read':()=>toast('Marked read in this preview. Durable inbox/read state is proposed.'),
 'test-router':()=>toast('Demo test: connection accepted. No network request was made.'),
 'save-router':()=>enqueue('Router configuration saved in demo; not a connectivity test'),
 'refresh-router':()=>confirmDialog('Refresh and reconcile?', 'The current Web action logs into the router, reconciles speed policies and records usage. It may apply configured limits immediately. This preview makes no network request.', 'Run demo refresh',()=>toast('Demo refresh complete. Sample reading time remains 21:39.')),
 'reapply':()=>confirmDialog('Force reapply speed policies?', 'Current code bumps policy versions and attempts an immediate Web write, falling back to the Agent next tick. Automatic dry-run does not guard base policies.', 'Request demo reapply',()=>toast('Demo reapply path reviewed. No router was contacted.')),
 'save-policies':()=>enqueue('Category speed policies saved'),
 'speed':()=>openSheet('Category speed policy',`<div class="form-stack"><label class="field">Category<select><option>Television</option><option>All categories · bulk draft</option></select></label><label class="check-row"><input type="checkbox" checked><span>Limit enabled</span></label><div class="form-grid"><label class="field">Download · Mbps<input type="number" min="0.001" value="8"></label><label class="field">Upload · Mbps<input type="number" min="0.001" value="2"></label></div><p class="hint">Independent speeds stored in Kbps. Bulk fill is only a draft until Save all. Quota/rule dry-run does not guard base speed policies.</p></div>`,button('Cancel','close-editor','outline')+button('Save policy','speed-save','button')),
 'speed-save':()=>{closeSheet(true);enqueue('Speed policy saved');},
 'identity':()=>openSheet('Device identity',`<div class="form-stack"><div class="preview-label">Local ownership persistence required</div><label class="field">Friendly name<input id="identity-name" maxlength="80" value="Samsung TV"></label><label class="field">Category override<select><option>Television</option><option>Use router category</option></select></label><p class="hint">Changes should survive discovery. Router-reported identity stays visible. This prototype changes only the demo name.</p></div>`,button('Cancel','close-editor','outline')+button('Save identity','save-identity','button')),
 'save-identity':()=>{const value=$('#identity-name').value.trim();if(!value){$('#identity-name').setCustomValidity('Enter a name.');$('#identity-name').reportValidity();return;}devices[1].name=value;closeSheet(true);render(false);toast('Demo friendly name updated locally.');},
 'budget':()=>openSheet('Household ISP budget',`<div class="preview-label">New backend required</div><div class="form-stack"><label class="field">Monthly allowance · GB<input type="number" value="300" min="1"></label><label class="field">Billing-cycle start day<input type="number" value="1" min="1" max="31"></label><p class="hint">Not the default per-device quota. Days 29–31 clamp to month end. Current quota periods stay calendar-based until an explicit migration.</p></div>`,button('Close preview','close-editor','button')),
 'graduate':()=>openSheet('Graduate one policy at a time',`<p>Live counter comparison and T8 verification remain outstanding. A checked box in this preview is not evidence.</p><ol><li>Record verified units, paths and recovery tests.</li><li>Confirm protected devices, fresh Agent config and Android delivery.</li><li>Change Docker forced mode outside the browser, leaving individual rules dry-run.</li><li>Test one reversible throttle and release before expanding.</li></ol><p class="hint">This preview does not enable enforcement.</p>`,button('Keep observing','close-editor','button')),
 'auth-preview':()=>openSheet('Proposed administrator sign-in',`<p>Set one admin password locally, then sign in over trusted HTTPS. Server validates a stored password hash and issues an HttpOnly session cookie.</p><p class="hint">Rate-limit failures, require antiforgery on browser writes, support revocation and local recovery. Tailnet access is an additional boundary, not a dashboard session.</p>`,button('Close','close-editor','button')),
 'reboot':()=>confirmDialog('Reboot the whole network?', 'Every device can disconnect. The current endpoint is not live-verified. Reboot cannot be undone. No command will be sent by this design preview.', 'Review demo reboot',()=>toast('Demo only: reboot command-sent feedback reviewed. Real recovery remains unverified.')),
 'backup':()=>toast('Design preview: coherent encrypted DB + key-ring backup; no file created.'),
 'restore-backup':()=>confirmDialog('Review restore plan?', 'Production must validate an encrypted bundle, enter maintenance mode across both hosts and back up current state. This preview will not read or replace data.', 'Review only',()=>toast('Restore rehearsal is a future implementation gate. No files changed.')),
 'install':()=>openSheet('Install on Android',`<p>On the real trusted HTTPS origin, use Chrome’s “Add to home screen” or Install control when available. You can receive push without installing.</p><p class="hint">A file:// preview cannot exercise install prompts, service worker delivery or an offline Blazor circuit. Proposed offline shell shows guidance only.</p>`,button('Got it','close-editor','button')),
 'setup-test':()=>{state.setupTested=true;render(false);toast('Demo connection test passed. No router was contacted.');},
 'setup-notifications':()=>{state.notifications=true;toast('Demo notification setup complete. No OS permission prompt.');},
 'retry':()=>{state.scenario='dry';$('#scenario').value='dry';render(false);toast('Demo read recovered.');},
 'clear-selection':()=>{state.selected.clear();renderDevices();},
 'clear-filters':()=>{state.deviceSearch='';state.category='all';state.online='all';render(false);},
 'export':()=>{const internetTotal=state.period==='day'?8.4:state.period==='week'?111.6:214; const lanTotal=state.period==='day'?24:state.period==='week'?122:196; const periodLabel=state.period==='day'?'2026-10-16':state.period==='week'?'2026-10-10_to_2026-10-16':'2026-10-01_to_2026-10-16'; const rows=['device,mac,internet_bytes,lan_bytes,period,timezone',...devices.map(d=>`"${(/^[=+@-]/.test(d.name)?"'":'')+d.name.replace(/"/g,'""')}",${mac(d)},${Math.round(d.used/8.4*internetTotal*1e9)},${Math.round(d.lan/24*lanTotal*1e9)},${periodLabel},Africa/Cairo`)];const blob=new Blob([rows.join('\r\n')+'\r\n'],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='netpilot-DEMO-'+state.period+'-2026-10-16.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported fictional per-device totals for the selected period. Byte values are sample estimates.');}
 };
 if(actions[action])actions[action]();
}
function renderSearch(query){
 const items=[...devices.map(d=>[d.name,'/devices/'+mac(d),d.type]),['Home','/','home'],['Usage','/usage','usage'],['Quotas','/automations/quotas','usage'],['Bedtime throttle','/automations/rules','clock'],['Notifications','/settings/notifications','bell'],['Safety Center','/settings/safety','shield'],['Router settings','/settings/router','router']];
 const results=items.filter(([t])=>t.toLowerCase().includes(query.toLowerCase()));
 $('#search-results').innerHTML=results.length?results.map(([t,r,i])=>`<a href="#${r}">${icon(i)}${esc(t)}</a>`).join(''):'<p class="hint">No matches. Try a device or page name.</p>';
}
document.addEventListener('click',event=>{
 const action=event.target.closest('[data-action]');if(action){handleAction(action.dataset.action);return;}
 const period=event.target.closest('[data-period]');if(period){state.period=period.dataset.period;render(false);return;}
 const template=event.target.closest('[data-template]');if(template){ruleEditor(template.dataset.template);return;}
 if(event.target.closest('#search-results a'))$('#search-dialog').close();
});
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.id==='device-search'){state.deviceSearch=el.value;renderDevices();}
 if(el.id==='global-search')renderSearch(el.value);
 if(el.closest('#editor'))state.dirty=true;
 if(el.id==='quota-range'){$('#quota-cap').value=el.value;updateQuotaPreview();}
 if(el.id==='quota-cap')updateQuotaPreview();
 if(el.id==='identity-name')el.setCustomValidity('');
 if(el.id==='bonus-amount')el.setCustomValidity('');
});
function updateQuotaPreview(){if($('#quota-preview'))$('#quota-preview').textContent=`Samsung TV → Television → ${$('#quota-cap').value||'no'} GB/day → ${$('#quota-action').value}`;}
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.id==='scenario'){state.scenario=el.value;render(false);}
 if(el.id==='theme-select')setTheme(el.value);
 if(el.id==='seed'){if(el.value==='teal')document.documentElement.removeAttribute('data-seed');else document.documentElement.dataset.seed=el.value;}
 if(el.id==='category-filter'){state.category=el.value;renderDevices();}
 if(el.id==='online-filter'){state.online=el.value;renderDevices();}
 if(el.id==='group-filter'){state.group=el.value;renderDevices();}
 if(el.dataset.device){if(el.checked)state.selected.add(el.dataset.device);else state.selected.delete(el.dataset.device);renderDevices();}
 if(el.id==='activity-filter'){state.activity=el.value;render(false);}
 if(el.id==='quota-action'){$('#quota-rate').disabled=el.value!=='Throttle';updateQuotaPreview();}
 if(el.id==='rule-trigger'){state.ruleTrigger=el.value;if(state.ruleTrigger!=='Time window'&&state.ruleRevert==='When time window ends')state.ruleRevert='At period end';$('#trigger-fields').innerHTML=triggerFields();}
 if(el.id==='rule-action'){state.ruleAction=el.value;$('#action-fields').innerHTML=actionFields();}
 if(el.id==='protect-tv'){state.protectedTV=el.checked;enqueue(el.checked?'Protection enabled':'Protection removal requested');}
 if(el.id==='lan-only'){const checked=el.checked;el.checked=!checked;confirmDialog('Change LAN-only usage classification?', 'All future traffic becomes LAN, including real Internet usage. History and TV traffic stay unchanged. This is a demo flag change.', 'Confirm classification',()=>enqueue('LAN-only classification change requested'));}
});
document.addEventListener('submit',event=>{
 if(event.target.id!=='quota-form')return;event.preventDefault();
 const data=new FormData(event.target);const cap=Number(data.get('cap'));const warnings=String(data.get('warnings')).trim();const values=warnings?warnings.split(',').map(v=>Number(v.trim())):[];
 if(!Number.isFinite(cap)||cap<=0||values.some((v,i)=>!Number.isInteger(v)||v<1||v>99||(i>0&&v<=values[i-1]))){$('#quota-error').textContent='Use a positive cap and sorted, distinct warning percentages from 1–99.';$('#quota-cap').focus();return;}
 if(data.get('action')==='Throttle'&&(!Number.isInteger(Number(data.get('rate')))||Number(data.get('rate'))<=0)){$('#quota-error').textContent='Enter a positive whole-number throttle in Kbps.';$('#quota-rate').focus();return;}
 state.quota=cap;state.quotaAction=String(data.get('action'));state.quotaDry=data.has('dry');closeSheet(true);enqueue('Quota saved; draft preview updated');
});
$('#editor').addEventListener('cancel',event=>{event.preventDefault();closeSheet();});
$('#search-dialog').addEventListener('close',()=>{if(lastOpener&&lastOpener.isConnected)lastOpener.focus();});
document.addEventListener('keydown',event=>{
 const typing=event.target.matches('input,textarea,select,[contenteditable]');
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&!$('#editor').open&&!$('#confirm').open){event.preventDefault();if(!$('#search-dialog').open)handleAction('search');}
 if(event.key==='/'&&!typing&&!$('dialog[open]')){event.preventDefault();handleAction('search');}
 if(event.key==='?'&&!typing&&!$('dialog[open]'))toast('Keyboard: Ctrl/⌘ K or / opens search; Escape closes a dialog. Tab moves between controls.');
});
window.addEventListener('hashchange',()=>{if(location.hash!=='#main')render();});
$('.skip').addEventListener('click',event=>{event.preventDefault();$('#main').focus();});
$('[data-action="search"]').innerHTML=icon('search');
$('[data-action="theme"]').innerHTML=icon('moon');
$('.settings-link').innerHTML=icon('settings')+'<span class="settings-label">Settings</span>';
initTheme();render(false);
